"""Narrow cleanup, exact payload checks, and retained final generated bytes."""

import plistlib
import shutil
import stat
from types import SimpleNamespace
from unittest import mock

from helper_support import Fixture, GitFixture, ROOT, cwd, original, source
import native
import repository


class NativeTests(Fixture):
    def populate(self, binary=False):
        self.sources()
        for path in native.GENERATED_FILES:
            self.write(path, b"fresh native bytes")
        for name in ("manifest.json", "constants.xlf"):
            self.write(name, original(name))
            self.write(native.BUNDLE / "Contents/Resources" / name, original(name))
        value = plistlib.loads((self.root / source.PLIST).read_bytes())
        self.write(native.BUNDLE / "Contents/Info.plist", plistlib.dumps(
            value, fmt=plistlib.FMT_BINARY if binary else plistlib.FMT_XML))
        self.write(native.BUNDLE / "Contents/Resources" / source.LOCALIZED,
                   (self.root / source.LOCALIZED).read_bytes())
        return source.read(ROOT)

    def test_xml_and_binary_metadata_unsigned_and_signed_gates_are_separate(self):
        for binary in (False, True):
            version = self.populate(binary)
            with cwd(self.root):
                native.validate_assets(version)
                native.FILES[-1].unlink()
                native.validate_built(version)
                with self.assertRaises(ValueError):
                    native.validate_assets(version)

    def test_final_all_generated_leaves_require_nonempty_regular_nonsymlink(self):
        version = self.populate()
        for path in native.GENERATED_FILES:
            with self.subTest(path=path):
                target = self.root / path
                saved = target.read_bytes()
                for kind in ("missing", "empty", "directory", "symlink"):
                    with self.subTest(kind=kind):
                        target.unlink()
                        if kind == "empty":
                            target.write_bytes(b"")
                        elif kind == "directory":
                            target.mkdir()
                        elif kind == "symlink":
                            external = self.write("external/bytes", saved)
                            target.symlink_to(external)
                        with cwd(self.root), self.assertRaises(ValueError):
                            native.validate_assets(version)
                        if target.is_dir() and not target.is_symlink():
                            target.rmdir()
                        else:
                            target.unlink(missing_ok=True)
                        target.write_bytes(saved)
        with cwd(self.root):
            native.validate_assets(version)

    def test_metadata_localization_resources_and_download_are_revalidated(self):
        version = self.populate()
        paths = (native.FILES[1], native.FILES[2], native.FILES[3],
                 native.FILES[4], native.DOWNLOADS[0])
        for path in paths:
            with self.subTest(path=path):
                target = self.root / path
                saved = target.read_bytes()
                target.write_bytes(b"late substitution")
                with cwd(self.root), self.assertRaises((ValueError, plistlib.InvalidFileException)):
                    native.validate_assets(version)
                target.write_bytes(saved)
        with cwd(self.root), self.assertRaises(ValueError):
            native.validate_built("99.0.0")

    def test_selective_cleanup_preserves_all_packaged_siblings_and_static_dependencies(self):
        protected = (
            native.BUNDLE / "Contents/QuickLook/Thumbnail.png",
            native.BUNDLE / "Contents/MacOS/runtime.dylib",
            native.BUNDLE / "Contents/Resources/custom.txt",
            native.WINDOWS_BINARY,
            native.BASE / "Default/keep", native.BASE / "Other.bundle/keep",
            "build/unrelated/keep", "a/libced.a", "a/libjsoncpp.a",
            "lib/windows64/ced.lib", "test/Project/source",
        )
        for path in protected:
            self.write(path, b"preserved")
        for path in native.FILES:
            self.write(path, b"stale")
        for path in native.DIRECTORIES:
            self.write(path / "intermediate", b"stale")
        with cwd(self.root):
            native.prepare()
            native.prepare()
        for path in protected:
            self.assertEqual((self.root / path).read_bytes(), b"preserved")
        for path in (*native.FILES, *native.DIRECTORIES):
            self.assertFalse((self.root / path).exists())

    def test_symlink_and_reparse_prevalidated_before_any_deletion(self):
        for where in (native.FILES[-1], native.DIRECTORIES[-1], native.BUNDLE,
                      native.DIRECTORIES[0] / "nested/link"):
            with self.subTest(where=where):
                first = self.write(native.FILES[0], b"must remain")
                destination = self.write("outside/keep", b"untouched")
                link = self.root / where
                if link.is_dir():
                    shutil.rmtree(link)
                link.parent.mkdir(parents=True, exist_ok=True)
                link.symlink_to(destination)
                with cwd(self.root), self.assertRaisesRegex(ValueError, "symlink"):
                    native.prepare()
                if where != native.BUNDLE:
                    self.assertEqual(first.read_bytes(), b"must remain")
                self.assertEqual(destination.read_bytes(), b"untouched")
                link.unlink()
        first = self.write(native.FILES[0], b"must remain")
        self.write(native.DIRECTORIES[0] / "obj", b"untouched")
        real = type(first).lstat

        def reparse(path, *args, **kwargs):
            result = real(path, *args, **kwargs)
            return (SimpleNamespace(st_mode=stat.S_IFDIR, st_file_attributes=0x400)
                    if path == native.DIRECTORIES[0] else result)

        with cwd(self.root), mock.patch("pathlib.Path.lstat", new=reparse):
            with self.assertRaisesRegex(ValueError, "reparse"):
                native.prepare()
        self.assertEqual(first.read_bytes(), b"must remain")

    def test_cleanup_io_error_is_fatal(self):
        self.write(native.FILES[0], b"stale")
        with cwd(self.root), mock.patch("pathlib.Path.unlink", side_effect=PermissionError("denied")):
            with self.assertRaises(PermissionError):
                native.prepare()
        self.write(native.DIRECTORIES[0] / "stale", b"stale")
        with cwd(self.root), mock.patch("shutil.rmtree", side_effect=PermissionError("denied")):
            with self.assertRaises(PermissionError):
                native.prepare()

    def test_xcode_data_is_never_recursively_cleaned(self):
        paths = ("build/XCBuildData/build.db", "build/XCBuildData/unexpected-source.cpp",
                 "build/XCBuildData/evil.xcbuilddata/keep")
        for path in paths:
            self.write(path, b"preserve original bytes")
        with cwd(self.root):
            native.prepare()
        for path in paths:
            self.assertEqual((self.root / path).read_bytes(), b"preserve original bytes")

    def test_merge_uses_only_exact_download_and_prevalidates_target(self):
        self.write(native.DOWNLOADS[0], b"fresh")
        self.write(native.WINDOWS_BINARY, b"previous")
        with cwd(self.root):
            native.merge_windows()
            native.verify_windows()
        binary = self.root / native.WINDOWS_BINARY
        binary.unlink()
        binary.symlink_to(self.write("outside/keep", b"untouched"))
        with cwd(self.root), self.assertRaises(ValueError):
            native.merge_windows()
        self.assertEqual((self.root / "outside/keep").read_bytes(), b"untouched")


class GeneratedRetentionTests(GitFixture):
    def test_native_leaves_and_exact_xcode_database_are_final_only(self):
        for relative in (
            *native.GENERATED_FILES,
            "build/XCBuildData/build.db", "build/XCBuildData/build.db-wal",
            "build/XCBuildData/build.db-shm",
            "build/XCBuildData/0123456789abcdef0123456789abcdef.xcbuilddata/build-request.json",
            "build/Compact Encoding Detection.build/Default/object.o",
        ):
            target = self.local / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(b"fresh native output")
        with cwd(self.local):
            with self.assertRaises(ValueError):
                repository.verify_checkout(self.sha, generated=native.generated)
            repository.verify_checkout(self.sha, generated=native.generated, final=True)

    def test_evil_siblings_and_nongenerated_resources_remain_protected(self):
        for relative in (
            "build/XCBuildData-evil/build.db", "build/XCBuildData/unexpected-source.cpp",
            "build/XCBuildData/build.db-evil",
            "build/XCBuildData/evil.xcbuilddata/build-request.json",
            "build/Compact Encoding Detection.build-evil/main.o",
            "build/unexpected-source.cpp", "Objs/Release-evil/main.obj",
            "winbuild/nested/Compact Encoding Detection.4DX",
            str(native.BUNDLE / "Contents/QuickLook/Thumbnail.png"),
            str(native.BUNDLE / "Contents/Resources/custom.txt"),
            str(native.BUNDLE / "Contents/_CodeSignature/evil"),
        ):
            with self.subTest(relative=relative):
                target = self.local / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(b"unexpected")
                with cwd(self.local), self.assertRaises(ValueError):
                    repository.verify_checkout(self.sha, generated=native.generated, final=True)
                target.unlink()
